#include <bits/stdc++.h>
int main(int c, char** v) { std::mt19937 r(atoi(v[1])); int n = r() % 5 + 1; std::vector<std::array<int,3>> e; for (int i = 2; i <= n; i++) e.push_back({int(r() % (i - 1) + 1), i, int(r() % 3 + 1)}); int extra = r() % 4; std::set<std::pair<int,int>> seen; for (auto [a, b, w] : e) seen.insert({a, b}); while (extra--) { int a = r() % n + 1, b = r() % n + 1; if (a > b) std::swap(a, b); if (a != b && !seen.count({a, b})) { seen.insert({a, b}); e.push_back({a, b, int(r() % 3 + 1)}); } } std::shuffle(e.begin(), e.end(), r); printf("%d %d\n", n, (int)e.size()); for (auto [a, b, w] : e) printf("%d %d %d\n", a, b, w); printf("%d\n", int(r() % n + 1)); }
